#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

vector<long long> pattern(20), base_pow(20);
int min_step = -1;

void setup()
{
    base_pow[0] = 1;
    for (int i = 1; i <= 17; ++i)
        base_pow[i] = base_pow[i - 1] * 10;

    pattern[0] = 0;
    for (int i = 1; i <= 17; ++i)
        pattern[i] = pattern[i - 1] * 10 + 1;
}

int get_digits(long long num)
{
    int count = 0;
    do
    {
        ++count;
        num /= 10;
    } while (num != 0);
    return count;
}

void dfs(int digit, long long val, int steps)
{
    if (min_step != -1 && steps >= min_step)
        return;
    if (val == 0 || digit == 0)
    {
        if (min_step == -1 || steps < min_step)
            min_step = steps;
        return;
    }
    if (val < 0)
        val = -val;

    long long temp_val = val;
    int temp_steps = 0;
    while (temp_val >= base_pow[digit - 1])
    {
        temp_val -= pattern[digit];
        temp_steps += digit;
    }
    dfs(digit - 1, temp_val, steps + temp_steps);

    temp_val = pattern[digit + 1] - val;
    temp_steps = 0;
    while (temp_val >= base_pow[digit - 1])
    {
        temp_val -= pattern[digit];
        temp_steps += digit;
    }
    dfs(digit - 1, temp_val, steps + digit + 1 + temp_steps);
}

int main()
{
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    setup();

    long long num;
    cin >> num;
    min_step = -1;
    dfs(get_digits(num), num, 0);
    cout << min_step << "\n";

    return 0;
}
